#!/usr/bin/env python3
"""Extract HE capability initialization, firmware TLVs, and BSS HE command."""
from pathlib import Path
import re,subprocess,tempfile
root=Path(__file__).resolve().parents[2]
src=(root/'SimpleMtkWlan/hal_mwx/MtkMwx.cpp').read_text();regs=(root/'SimpleMtkWlan/hal_mwx/if_mwxreg.h').read_text()
def fn(name):
 m=re.search(r'(?m)^(?:static )?(?:void|int)\n'+name+r'\(',src);assert m,name
 a=src.index('{',m.start());d=1;i=a+1
 while d:d+=(src[i]=='{')-(src[i]=='}');i+=1
 return src[m.start():i]

pre='\n#include <cassert>\n#include <cstdint>\n#include <cstdio>\n#include <cstring>\n#include <vector>\nstruct mbuf { std::vector<uint8_t> data; size_t lead=256; };\nusing mbuf_t=mbuf*;\nstatic unsigned hweight8(uint8_t x){return __builtin_popcount(unsigned(x));}\nstatic void *mwx_append_len(mbuf *m,int len){size_t at=m->data.size();m->data.resize(at+len);return m->data.data()+at;}\nvoid *mwx_append_tlv(mbuf*,uint16_t*,int,int);\nvoid *mwx_append_tlv(mbuf *m,uint16_t *n,int tag,int len){auto p=mwx_append_len(m,len+4);uint16_t hdr[]={(uint16_t)tag,(uint16_t)len};memcpy(p,hdr,4);(*n)++;return (uint8_t*)p+4;}\n#define htole16(x) (x)\n#define htole32(x) (x)\n#define le16toh(x) (x)\n#define le32toh(x) (x)\n#define IEEE80211_AID(x) ((x)&0x3fff)\nstruct ieee80211_he_cap_elem {uint8_t mac_cap_info[6];uint8_t phy_cap_info[11];};\nstruct ieee80211_he_mcs_nss_supp {uint16_t rx_mcs_80,tx_mcs_80,rx_mcs_160,tx_mcs_160,rx_mcs_80p80,tx_mcs_80p80;};\nstruct ieee80211com {ieee80211_he_cap_elem ic_he_cap_elem{};ieee80211_he_mcs_nss_supp ic_he_mcs_nss_supp{};uint8_t ic_ppe_thres[25]={};};\nstruct ieee80211_node {unsigned ni_associd=0x42;unsigned ni_flags=0x200000;uint16_t ni_htcaps=0,ni_vhtcaps=0;ieee80211_he_cap_elem ni_he_cap_elem{};ieee80211_he_mcs_nss_supp ni_he_mcs_nss_supp{};};\nstruct ifnet {int x;};\nstruct mwx_vif {uint8_t idx=3;};\nstruct bss_info_uni_he {uint16_t tag;uint16_t len;uint16_t he_rts_thres;uint8_t he_pe_duration;uint8_t su_disable;uint16_t max_nss_mcs[3];uint8_t rsv[2];};\nstruct bss_info_uni_bss_color {uint16_t tag;uint16_t len;uint8_t enable;uint8_t bss_color;uint8_t rsv[2];};\nstatic int send_result=0;\nstatic int mwx_send_assoc_status(struct mwx_softc*,uint32_t,const void*,size_t){return send_result;}\nstruct mwx_softc {struct {unsigned num_streams=2;unsigned has_2ghz=1,has_5ghz=1;} sc_capa;int sc_vht160=1;int sc_he_enabled=1;struct ieee80211com sc_ic;struct ifnet ifp;mwx_vif sc_vif;};\nconstexpr unsigned IEEE80211_HE_MCS_SUPPORT_0_11=2;\nconstexpr unsigned IEEE80211_HE_MCS_NOT_SUPPORTED=3;\n#define IEEE80211_HE_MAC_CAP0_HTC_HE 0x01\n#define IEEE80211_HE_MAC_CAP1_TF_MAC_PAD_DUR_16US 0x08\n#define IEEE80211_HE_MAC_CAP1_TF_MAC_PAD_DUR_MASK 0x0c\n#define IEEE80211_HE_MAC_CAP3_OMI_CONTROL 0x02\n#define IEEE80211_HE_MAC_CAP3_MAX_AMPDU_LEN_EXP_VHT_2 0x10\n#define IEEE80211_HE_MAC_CAP3_MAX_AMPDU_LEN_EXP_MASK 0x18\n#define IEEE80211_HE_MAC_CAP4_AMDSU_IN_AMPDU 0x40\n#define IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_40MHZ_IN_2G 0x02\n#define IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_40MHZ_80MHZ_IN_5G 0x04\n#define IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_160MHZ_IN_5G 0x08\n#define IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_RU_MAPPING_IN_2G 0x20\n#define IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_RU_MAPPING_IN_5G 0x40\n#define IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_MASK 0xfe\n#define IEEE80211_HE_PHY_CAP1_DEVICE_CLASS_A 0x10\n#define IEEE80211_HE_PHY_CAP1_LDPC_CODING_IN_PAYLOAD 0x20\n#define IEEE80211_HE_PHY_CAP1_HE_LTF_AND_GI_FOR_HE_PPDUS_0_8US 0x40\n#define IEEE80211_HE_PHY_CAP1_PREAMBLE_PUNC_RX_MASK 0x0f\n#define IEEE80211_HE_PHY_CAP8_20MHZ_IN_40MHZ_HE_PPDU_IN_2G 0x02\n#define IEEE80211_HE_PHY_CAP9_NOMIMAL_PKT_PADDING_16US 0x80\n#define IEEE80211_HE_PHY_CAP2_NDP_4x_LTF_AND_3_2US 0x02\n#define IEEE80211_HE_PHY_CAP3_DCM_MAX_CONST_TX_QPSK 0x02\n#define IEEE80211_HE_PHY_CAP3_DCM_MAX_TX_NSS_2 0x04\n#define IEEE80211_HE_PHY_CAP3_DCM_MAX_CONST_RX_QPSK 0x10\n#define IEEE80211_HE_PHY_CAP3_DCM_MAX_RX_NSS_2 0x20\n#define IEEE80211_HE_PHY_CAP4_SU_BEAMFORMEE 0x01\n#define IEEE80211_HE_PHY_CAP4_BEAMFORMEE_MAX_STS_UNDER_80MHZ_4 0x0c\n#define IEEE80211_HE_PHY_CAP4_BEAMFORMEE_MAX_STS_ABOVE_80MHZ_4 0x60\n#define IEEE80211_HE_PHY_CAP5_NG16_SU_FEEDBACK 0x40\n#define IEEE80211_HE_PHY_CAP5_NG16_MU_FEEDBACK 0x80\n#define IEEE80211_HE_PHY_CAP6_CODEBOOK_SIZE_42_SU 0x01\n#define IEEE80211_HE_PHY_CAP6_CODEBOOK_SIZE_75_MU 0x02\n#define IEEE80211_HE_PHY_CAP6_TRIG_CQI_FB 0x10\n#define IEEE80211_HE_PHY_CAP6_PARTIAL_BW_EXT_RANGE 0x20\n#define IEEE80211_HE_PHY_CAP6_PPE_THRESHOLD_PRESENT 0x80\n#define IEEE80211_HE_PHY_CAP7_POWER_BOOST_FACTOR_AR 0x02\n#define IEEE80211_HE_PHY_CAP7_HE_SU_MU_PPDU_4XLTF_AND_08_US_GI 0x04\n#define IEEE80211_HE_PHY_CAP8_20MHZ_IN_160MHZ_HE_PPDU 0x04\n#define IEEE80211_HE_PHY_CAP8_80MHZ_IN_160MHZ_HE_PPDU 0x08\n#define IEEE80211_HE_PHY_CAP8_DCM_MAX_RU_484 0x40\n#define IEEE80211_HE_PHY_CAP9_LONGER_THAN_16_SIGB_OFDM_SYM 0x01\n#define IEEE80211_HE_PHY_CAP9_NON_TRIGGERED_CQI_FEEDBACK 0x02\n#define IEEE80211_HE_PHY_CAP9_TX_1024_QAM_LESS_THAN_242_TONE_RU 0x04\n#define IEEE80211_HE_PHY_CAP9_RX_1024_QAM_LESS_THAN_242_TONE_RU 0x08\n#define IEEE80211_HE_PHY_CAP9_RX_FULL_BW_SU_USING_MU_WITH_COMP_SIGB 0x10\n#define IEEE80211_HE_PHY_CAP9_RX_FULL_BW_SU_USING_MU_WITH_NON_COMP_SIGB 0x20\n#define IEEE80211_PPE_THRES_NSS_POS 0\n#define IEEE80211_PPE_THRES_RU_INDEX_BITMASK_POS 3\n#define IEEE80211_PPE_THRES_INFO_PPET_SIZE 3\n#define __packed\nconstexpr uint16_t STA_REC_HE=0x06,STA_REC_HE_V2=0x19;\nconstexpr unsigned STA_REC_HE_CAP_PARTIAL_BW_EXT_RANGE=0x100,STA_REC_HE_CAP_SU_MU_PPDU_4LTF_8US_GI=0x4000,STA_REC_HE_CAP_TRIG_CQI_FK=0x80,STA_REC_HE_CAP_TX_1024QAM_UNDER_RU242=0x80000,STA_REC_HE_CAP_RX_1024QAM_UNDER_RU242=0x100000;\nconstexpr uint16_t UNI_BSS_INFO_HE_BASIC=5,UNI_BSS_INFO_BSS_COLOR=4;\nconstexpr uint32_t MCU_UNI_CMD_BSS_INFO_UPDATE=0x20002;\n#define MWX_DEV_LOG(...) ((void)0)\nenum {CMD_HE_MCS_BW80=0,CMD_HE_MCS_BW160,CMD_HE_MCS_BW8080,CMD_HE_MCS_BW_NUM};\nstruct sta_rec_he {\n\tuint16_t\ttag; uint16_t\tlen; uint32_t\the_cap;\n\tuint8_t\t\tt_frame_dur; uint8_t\tmax_ampdu_exp; uint8_t\tbw_set; uint8_t\tdevice_class;\n\tuint8_t\t\tdcm_tx_mode; uint8_t\tdcm_tx_max_nss; uint8_t\tdcm_rx_mode; uint8_t\tdcm_rx_max_nss;\n\tuint8_t\t\tdcm_max_ru; uint8_t\tpunc_pream_rx; uint8_t\tpkt_ext; uint8_t\trsv1;\n\tuint16_t\tmax_nss_mcs[CMD_HE_MCS_BW_NUM]; uint8_t\trsv2[2];\n} __packed;\nstruct sta_rec_he_v2 {\n\tuint16_t\ttag; uint16_t\tlen; uint8_t\the_mac_cap[6]; uint8_t\the_phy_cap[11];\n\tuint8_t\t\tpkt_ext; uint16_t\tmax_nss_mcs[CMD_HE_MCS_BW_NUM];\n} __packed;\nconstexpr unsigned STA_REC_HE_CAP_HTC=1,STA_REC_HE_CAP_OM=8,STA_REC_HE_CAP_AMSDU_IN_AMPDU=16,STA_REC_HE_CAP_LDPC=64,STA_REC_HE_CAP_SU_PPDU_1LTF_8US_GI=0x2000,STA_REC_HE_CAP_BW20_RU242_SUPPORT=0x40000;\n'
main='\nint main(){\n mwx_softc sc{};ieee80211com ic{};sc.sc_ic=ic;mwx_init_he_caps(&sc);\n assert(sc.sc_ic.ic_he_cap_elem.mac_cap_info[0]&IEEE80211_HE_MAC_CAP0_HTC_HE);\n assert(sc.sc_ic.ic_he_cap_elem.mac_cap_info[4]&IEEE80211_HE_MAC_CAP4_AMDSU_IN_AMPDU);\n assert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[0]&IEEE80211_HE_PHY_CAP0_CHANNEL_WIDTH_SET_160MHZ_IN_5G);\nassert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[6]&(IEEE80211_HE_PHY_CAP6_PARTIAL_BW_EXT_RANGE|IEEE80211_HE_PHY_CAP6_PPE_THRESHOLD_PRESENT));\n assert(sc.sc_ic.ic_ppe_thres[0]==0x79);for(unsigned i=0;i<25;i++)\n assert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[8]&(IEEE80211_HE_PHY_CAP8_20MHZ_IN_160MHZ_HE_PPDU|IEEE80211_HE_PHY_CAP8_80MHZ_IN_160MHZ_HE_PPDU));\nassert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[2]&IEEE80211_HE_PHY_CAP2_NDP_4x_LTF_AND_3_2US);\nassert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[4]&(IEEE80211_HE_PHY_CAP4_SU_BEAMFORMEE|IEEE80211_HE_PHY_CAP4_BEAMFORMEE_MAX_STS_UNDER_80MHZ_4|IEEE80211_HE_PHY_CAP4_BEAMFORMEE_MAX_STS_ABOVE_80MHZ_4));\nassert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[6]&(IEEE80211_HE_PHY_CAP6_PARTIAL_BW_EXT_RANGE|IEEE80211_HE_PHY_CAP6_PPE_THRESHOLD_PRESENT));\n assert(sc.sc_ic.ic_ppe_thres[0]==0x79);for(unsigned i=0;i<25;i++)\n assert(sc.sc_ic.ic_he_cap_elem.phy_cap_info[8]&(IEEE80211_HE_PHY_CAP8_20MHZ_IN_160MHZ_HE_PPDU|IEEE80211_HE_PHY_CAP8_80MHZ_IN_160MHZ_HE_PPDU));\n {uint16_t map=sc.sc_ic.ic_he_mcs_nss_supp.rx_mcs_80;assert((map&3)==2 && ((map>>2)&3)==2 && ((map>>4)&3)==3);}\n {uint16_t map=sc.sc_ic.ic_he_mcs_nss_supp.rx_mcs_160;assert((map&3)==2 && ((map>>2)&3)==2 && ((map>>4)&3)==3);}\n ieee80211_node ni{};ni.ni_he_cap_elem=sc.sc_ic.ic_he_cap_elem;ni.ni_he_mcs_nss_supp=sc.sc_ic.ic_he_mcs_nss_supp;mbuf m{};uint16_t count=0;mwx_add_sta_he_tlvs(&m,&count,&ni);\n assert(count==2&&m.data.size()==4+sizeof(sta_rec_he)+4+sizeof(sta_rec_he_v2));\n const auto*he=(const sta_rec_he*)(m.data.data()+4);\n const auto*v2=(const sta_rec_he_v2*)(m.data.data()+4+sizeof(sta_rec_he)+4);\n assert((he->he_cap&(STA_REC_HE_CAP_HTC|STA_REC_HE_CAP_OM|STA_REC_HE_CAP_AMSDU_IN_AMPDU|STA_REC_HE_CAP_LDPC|STA_REC_HE_CAP_SU_PPDU_1LTF_8US_GI|STA_REC_HE_CAP_BW20_RU242_SUPPORT|STA_REC_HE_CAP_PARTIAL_BW_EXT_RANGE|STA_REC_HE_CAP_SU_MU_PPDU_4LTF_8US_GI|STA_REC_HE_CAP_TRIG_CQI_FK|STA_REC_HE_CAP_TX_1024QAM_UNDER_RU242|STA_REC_HE_CAP_RX_1024QAM_UNDER_RU242))==(STA_REC_HE_CAP_HTC|STA_REC_HE_CAP_OM|STA_REC_HE_CAP_AMSDU_IN_AMPDU|STA_REC_HE_CAP_LDPC|STA_REC_HE_CAP_SU_PPDU_1LTF_8US_GI|STA_REC_HE_CAP_BW20_RU242_SUPPORT|STA_REC_HE_CAP_PARTIAL_BW_EXT_RANGE|STA_REC_HE_CAP_SU_MU_PPDU_4LTF_8US_GI|STA_REC_HE_CAP_TRIG_CQI_FK|STA_REC_HE_CAP_TX_1024QAM_UNDER_RU242|STA_REC_HE_CAP_RX_1024QAM_UNDER_RU242));\n assert(he->pkt_ext==2&&v2->pkt_ext==2);assert(v2->he_phy_cap[0]==ni.ni_he_cap_elem.phy_cap_info[0]);\n send_result=0;assert(mwx_send_bss_he_info(&sc,&ni)==0);send_result=99;assert(mwx_send_bss_he_info(&sc,&ni)==99);\n puts("PASS HE Linux-aligned capability/PPE and expanded STA_REC mapping (UBSan).");\n}\n'
with tempfile.TemporaryDirectory() as d:
 path=Path(d)/'test.cpp';path.write_text(pre+'\n'+fn('mwx_init_he_caps')+'\n'+fn('mwx_add_sta_he_tlvs')+'\n'+fn('mwx_send_bss_he_info')+'\n'+main)
 subprocess.run(['clang++','-std=c++14','-fsanitize=undefined','-fno-sanitize-recover=all','-g',str(path),'-o',str(Path(d)/'test')],check=True)
 subprocess.run([str(Path(d)/'test')],check=True)
